<div x-show="isSolo && isLeader && requests.length" class="border-t pt-6"><h3 class="font-medium mb-4">Join Requests (<span x-text="requests.length"></span>)</h3><div class="space-y-3"><template x-for="request in requests" :key="request.id"><div class="p-4 border rounded-lg bg-muted/30 flex flex-wrap items-start justify-between gap-3"><div><p class="font-medium" x-text="person(request.requester)"></p><p class="text-sm text-muted-foreground" x-text="email(request.requester)"></p><p class="text-sm mt-2 italic" x-text="request.message"></p></div><div class="flex gap-2"><x-capstone::button size="sm" variant="outline" @click="answer(request,false)" ::disabled="saving">Reject</x-capstone::button><x-capstone::button size="sm" @click="answer(request,true)" ::disabled="saving">Accept</x-capstone::button></div></div></template></div></div>
